//========================================================================================enum{	kTransferBufferSize = 4096};//========================================================================================// Global Functions//========================================================================================//----------------------------------------------------------------------------------------// SimpleHTTPDownload//----------------------------------------------------------------------------------------OSStatus SimpleHTTPDownload(const char *hostName,							const char *httpCommand,							const short destFileRefNum)	// Download a URL from the a web server.  hostName is a pointer	// to a string that contains the DNS address of the web server.	// The DNS address must be suffixed by ":<port>", where <port>	// is the port number the web server is operating on.	// httpCommand contains the HTTP command to send.  Typically this	// is of the form:	//	//		GET <x> HTTP/1.0\0x0d\0x0a\0x0d\0x0a	//	// where <x> is the URL path.  destFileRefNum is the file	// reference number to which the results of the HTTP command	// are written.  This routine does not parse the returned HTTP	// header in any way.  The entire incoming stream goes into	// the file verbatim.	//	// For example, if you were asked to download a URL like:	//	//		http://devworld.apple.com/dev/technotes.shtml	//	// you would set:	//	// 		o hostName to "devworld.apple.com:80" (80 is the	//		  default port for HTTP.	//		o httpCommand to "GET /dev/technotes.shtml HTTP/1.0\0x0d\0x0a\0x0d\0x0a"{	OSStatus err = noErr;	CThreadYielder_AC yielder;	CTCPEndpoint ep(&yielder);	Boolean bound = false;	try	{		// First allocate a buffer for storing the data as we read it.				CTextBuffer transferBuffer;		transferBuffer.reallocate(kTransferBufferSize);				// Now open a TCP endpoint.				ep.Open();				// If the endpoint opens successfully...				// Bind the endpoint.  Because we're an outgoing connection,		// we don't have to bind it to a specific address.						ep.Bind();		bound = true;					// Initialise the sndCall structure and call OTConnect.  We nil		// out most of the fields in the sndCall structure because		// we don't want any special options or connection data.		// The important field of the sndCall is the addr TNetBuf,		// which we initialise to the				CDNSAddress hostAddress(hostName);		ep.Connect(hostAddress);		// Send the HTTP command to the server.				ep.Send(httpCommand, OTStrLength(httpCommand));				// Now that we have sent the HTTP command, we turn around and		// receive the data coming back from the server.				long bytesReceived;		do		{			bytesReceived = ep.Receive(transferBuffer, kTransferBufferSize);						// Receive returns the number of bytes received.  Because we're in			// synchronous mode, it won't return until it's gotten something,			// or it gets an error.  						if (bytesReceived > 0)				ThrowIfOSErr_AC(FSWrite(destFileRefNum, &bytesReceived, transferBuffer));			// We keep running this loop until we get an eof.		}		while (bytesReceived >= 0);	}	catch (CException_AC& fi)	{		err = fi.GetError();	}		// Clean up.	if (bound)	{		OSStatus junk = ep.Unbind();		Warning_AC(junk, "SimpleHTTPDownload: OTUnbind failed.");	}	{		OSStatus junk = ep.Close();		Warning_AC(junk, "SimpleHTTPDownload: OTCloseProvider failed.");	}	return (err);}//----------------------------------------------------------------------------------------// End of SimpleHTTPDownload.cpp